function TechnicalReportPreview({ report }) { const c=report.context; return <Page title={report.title}><h3>1. IDENTIFICAÇÃO</h3><p>Interessado: {cell(c.owner.name)} · Imóvel: {cell(c.property.name)} · Matrícula: {cell(c.registry.registrationNumber)} · CNS: {cell(c.registry.cns)} · Cartório: {cell(c.registry.office)} · Comarca: {cell(c.registry.district)} · Município/UF: {cell(c.property.municipality)}/{cell(c.property.state)}</p><h3>2. OBJETO</h3><p>Apresentar esclarecimentos técnicos referentes ao levantamento georreferenciado e à descrição perimetral destinada ao procedimento registral.</p><h3>3. DOCUMENTOS ANALISADOS</h3><ul>{report.documents.length?report.documents.map((item)=><li key={item}>{item}</li>):<li>Nenhum documento de suporte vinculado.</li>}</ul><h3>4. IDENTIFICAÇÃO DO LEVANTAMENTO</h3><p>{cell(c.technical.name)} · {cell(c.technical.profession)} · {cell(c.technical.council)} {cell(c.technical.registrationNumber)} · Credenciamento {cell(c.technical.accreditation)} · ART/TRT {cell(c.technical.responsibilityTerm)} · Datum {cell(c.sigef.datum)} · Projeção/fuso {cell(c.property.projection)} / {cell(c.property.utmZone)}</p><h3>5. CARACTERIZAÇÃO</h3><p>Área: {cell(c.property.area)} ha · Perímetro: {cell(c.property.perimeter)} m · Vértices: {c.vertices.length} · Trechos: {c.boundaries.length}</p><h3>6. ANÁLISE TÉCNICA</h3><p>{report.analysis.walking} {report.analysis.closure}</p>{report.analysis.issues.length>0&&<ul>{report.analysis.issues.map((item)=><li key={item}>{item}</li>)}</ul>}<h3>7. CONFRONTAÇÕES</h3><table><thead><tr><th>TRECHO</th><th>CONFRONTANTE</th><th>MATRÍCULA</th><th>CNS</th><th>AZIMUTE</th><th>DISTÂNCIA</th><th>TIPO</th></tr></thead><tbody>{report.boundaryRows.map((row)=><tr key={`${row.fromVertex}-${row.toVertex}`}><td>{row.fromVertex} → {row.toVertex}</td><td>{row.boundaryName}</td><td>{value(row.boundaryRegistration)}</td><td>{value(row.boundaryCns)}</td><td>{row.azimuthDocumentRaw||row.azimuthDocument||"—"}</td><td>{row.distanceDocumentRaw||row.distanceDocument||"—"}</td><td>{row.boundaryType}</td></tr>)}</tbody></table><h3>8. CONCLUSÃO</h3><p>{report.conclusion}</p><h3>9. RESPONSABILIDADE TÉCNICA</h3><p>{cell(c.procedure.signatureMunicipality)}, {cell(c.procedure.requestDate)}.<br/>{cell(c.technical.name)} · {cell(c.technical.council)} {cell(c.technical.registrationNumber)} · Credenciamento {cell(c.technical.accreditation)} · ART/TRT {cell(c.technical.responsibilityTerm)}</p></Page>; }
