function ConsentPreview({ document }) { const b = document.boundary; return <><p>Propriedade denominada <strong>{fieldValue(document.property.name)}</strong>, matrícula {fieldValue(document.registry.registrationNumber)}, propriedade de {fieldValue(document.owner.name)}.</p><p>Área certificada SIGEF sob o código {fieldValue(document.sigef.certification)}.</p><h3>PROPRIETÁRIO DO IMÓVEL RETIFICANDO</h3><p>{fieldValue(document.owner.name)}, RG {fieldValue(document.owner.rg)}, CPF/CNPJ {fieldValue(document.owner.document)}.</p><h3>PROPRIETÁRIO DO IMÓVEL CONFRONTANTE</h3><p>{b.owner || "[DADO PENDENTE]"}, RG {b.rg || "[DADO PENDENTE]"}, CPF/CNPJ {b.document || "[DADO PENDENTE]"}, proprietário(a) do imóvel {b.propertyName || "[DADO PENDENTE]"}, matrícula {b.registration || "[DADO PENDENTE]"}, junto ao {b.office || "[DADO PENDENTE]"}.</p><p>As partes declaram não existir controvérsia ou litígio referente ao limite comum, reconhecendo a descrição técnica certificada como representação do trecho confrontante.</p><h3>DESCRIÇÃO DO TRECHO DE CONFRONTAÇÃO</h3><table><thead><tr><th>De</th><th>Para</th><th>Azimute</th><th>Distância</th><th>Longitude</th><th>Latitude</th><th>Altitude</th></tr></thead><tbody>{document.rows.map((row) => <tr key={`${row.from}-${row.to}`}><td>{row.from}</td><td>{row.to}</td><td>{row.azimuth}</td><td>{row.distance} m</td><td>{row.longitude}</td><td>{row.latitude}</td><td>{row.altitude === "" ? "—" : `${row.altitude} m`}</td></tr>)}</tbody></table><footer>{fieldValue(document.procedure.signatureMunicipality)}, {fieldValue(document.procedure.requestDate)}<br /><br />__________________________ &nbsp;&nbsp; __________________________<br />{fieldValue(document.owner.name)} &nbsp;&nbsp; {b.owner || "[DADO PENDENTE]"}<br /><br />__________________________<br />{fieldValue(document.technical.name)}<br />{fieldValue(document.technical.council)} {fieldValue(document.technical.registrationNumber)} · INCRA {fieldValue(document.technical.accreditation)} · {fieldValue(document.technical.responsibilityTerm)}</footer></>; }
function Checklist({ project, setProject }) {
  const [filter,setFilter]=useState("TODOS"); const [showProfile,setShowProfile]=useState(false); const [pendingReport,setPendingReport]=useState(false);
  const evaluation=evaluateCartorialChecklist(project); const profile=evaluation.profile||MATO_GROSSO_GEO_BASE;
  const matches=(item)=>filter==="TODOS"||(filter==="PENDENTES"&&["PENDING","REVIEW_REQUIRED"].includes(item.status))||(filter==="PRONTOS"&&["AVAILABLE","CONFIRMED"].includes(item.status))||(filter==="CONDICIONAIS"&&item.requiredLevel==="CONDITIONAL")||(filter==="CARTÓRIO"&&item.requiredLevel==="REGISTRY_PROFILE")||(filter==="CONFRONTANTES"&&item.category==="CONFRONTANTES")||(filter==="ÓRGÃOS"&&item.category==="ÓRGÃOS PÚBLICOS");
  const updateItem=(id,changes)=>setProject((current)=>applyChecklistOverride(current,id,changes));
  const attach=(item,file)=>{if(!file)return;const documentId=`checklist-${Date.now()}`;setProject((current)=>applyChecklistOverride({...current,sourceDocuments:[...(current.sourceDocuments||[]),{id:documentId,category:item.category,type:item.title,name:file.name,size:file.size,importedAt:new Date().toISOString(),status:"received"}]},item.id,{status:"AVAILABLE",documentIds:[...(item.documentIds||[]),documentId]}));};
  const saveProfile=(changes)=>setProject((current)=>({...current,registryOfficeProfile:createRegistryOfficeProfile({...profile,...changes,id:profile.id||undefined})}));
  const report=buildPendingRequirementsReport(project,evaluation);
  return <section><section className="gr-panel gr-readiness"><h3>CHECKLIST CARTORIAL INTELIGENTE</h3><div className="gr-progress"><strong>{evaluation.readiness.state} · {evaluation.readiness.percent}%</strong><i style={{width:`${evaluation.readiness.percent}%`}}/></div><p>{evaluation.readiness.state==="READY"?"PRONTO PARA REVISÃO FINAL":"Existem itens pendentes ou sujeitos a revisão."} {evaluation.readiness.disclaimer}</p><div className="gr-check-controls"><label>Tipo do proprietário<select value={project.ownerType||"NATURAL_PERSON"} onChange={(event)=>setProject((current)=>({...current,ownerType:event.target.value}))}><option value="NATURAL_PERSON">Pessoa física</option><option value="LEGAL_ENTITY">Pessoa jurídica</option></select></label><label><input type="checkbox" checked={Boolean(project.representation?.exists)} onChange={(event)=>setProject((current)=>({...current,representation:{...(current.representation||{}),exists:event.target.checked}}))}/> Existe procurador/representante</label><button onClick={()=>setShowProfile(!showProfile)}>PERFIL DO CARTÓRIO</button><button onClick={()=>setPendingReport(!pendingReport)}>GERAR RELATÓRIO DE PENDÊNCIAS</button></div></section>{showProfile&&<section className="gr-panel"><h3>PERFIL DO CARTÓRIO / SERVENTIA</h3><div className="gr-fields"><label><span>Nome</span><input value={profile.name||""} onChange={(event)=>saveProfile({name:event.target.value})}/></label><label><span>Município</span><input value={profile.city||""} onChange={(event)=>saveProfile({city:event.target.value})}/></label><label><span>UF</span><input value={profile.state||"MT"} onChange={(event)=>saveProfile({state:event.target.value})}/></label><label><span>CNS</span><input value={profile.cns||""} onChange={(event)=>saveProfile({cns:event.target.value})}/></label><label><span>Número da serventia</span><input value={profile.registryOfficeNumber||""} onChange={(event)=>saveProfile({registryOfficeNumber:event.target.value})}/></label></div><p>Exigências configuráveis:</p>{[["car","CAR"],["technical-report","Laudo técnico"],["rt-documents","Documentos do responsável técnico"],["interested-parties","Terceiros interessados"],["boundary-chain","Filiação dos confrontantes"]].map(([id,title])=>{const checked=profile.defaultRequirements?.some((item)=>item.id===id&&item.required);return <label className="gr-profile-rule" key={id}><input type="checkbox" checked={checked} onChange={(event)=>saveProfile({defaultRequirements:event.target.checked?[...(profile.defaultRequirements||[]).filter((item)=>item.id!==id),{id,title,required:true}]: (profile.defaultRequirements||[]).filter((item)=>item.id!==id)})}/>{title}</label>})}</section>}{pendingReport&&<section className="gr-panel"><h3>{report.title}</h3>{report.items.length?report.items.map((item)=><p key={item.number}><strong>{item.number}. {item.title}</strong><br/>{item.reason} · Prioridade {item.priority}</p>):<p>Nenhuma pendência obrigatória identificada.</p>}</section>}<section className="gr-panel"><h3>ALERTAS CARTORIAIS</h3><div className="gr-alert-grid">{evaluation.alerts.map((alert)=><article className={`gr-alert-${alert.priority}`} key={alert.id}><strong>{alert.priority}</strong><span>{alert.title}</span><small>{alert.reason}</small></article>)}</div></section><section className="gr-panel"><div className="gr-check-filters">{["TODOS","PENDENTES","PRONTOS","CONDICIONAIS","CARTÓRIO","CONFRONTANTES","ÓRGÃOS"].map((name)=><button className={filter===name?"active":""} key={name} onClick={()=>setFilter(name)}>{name}</button>)}</div>{CHECKLIST_CATEGORIES.map((category)=>{const items=evaluation.items.filter((item)=>item.category===category&&matches(item));return items.length?<section className="gr-smart-check-group" key={category}><h4>{category}</h4>{items.map((item)=><article key={item.id}><div><strong>{item.title}</strong><span className={`gr-check-status ${item.status}`}>{item.status}</span><small>{item.requiredLevel} · Fonte: {item.source}</small><p><b>Motivo:</b> {item.reason}</p>{item.documentIds?.length>0&&<small>{item.documentIds.length} documento(s) vinculado(s)</small>}</div><div className="gr-check-actions"><select value={item.status} onChange={(event)=>updateItem(item.id,{status:event.target.value})}>{["PENDING","AVAILABLE","CONFIRMED","NOT_APPLICABLE","REVIEW_REQUIRED"].map((status)=><option key={status}>{status}</option>)}</select><label>ANEXAR DOCUMENTO<input hidden type="file" onChange={(event)=>attach(item,event.target.files?.[0])}/></label><button onClick={()=>updateItem(item.id,{status:"CONFIRMED"})}>MARCAR RECEBIDO</button><button onClick={()=>updateItem(item.id,{status:"NOT_APPLICABLE"})}>NÃO APLICÁVEL</button><input value={item.notes||""} placeholder="Adicionar observação" onChange={(event)=>updateItem(item.id,{notes:event.target.value})}/></div></article>)}</section>:null})}</section></section>;
}
function Placeholder({ title, text, action }) { return <section className="gr-panel gr-placeholder"><h3>{title}</h3><p>{text}</p><button disabled>{action}</button></section>; }
function ParserDiagnostic({ diagnostic, project }) { const [raw, setRaw] = useState(false); const p = diagnostic.parsed; const valid = project.vertices.filter((v) => v.status === "OK"); const names = new Set(project.boundaries.map((item) => item.boundaryName).filter(Boolean)); const extracted = [["Imóvel", "property.name", project.property.name], ["Proprietário", "registry.owner", project.registry.owner], ["Matrícula", "registry.registrationNumber", project.registry.registrationNumber], ["CNS", "registry.cns", project.registry.cns], ["Município", "property.municipality", project.property.municipality], ["UF", "property.state", project.property.state], ["Área", "property.area", project.property.area], ["Perímetro", "property.perimeter", project.property.perimeter], ["Certificação", "sigef.certificationId", project.sigef.certificationId], ["Código da parcela", "sigef.parcelId", project.sigef.parcelId], ["Responsável técnico", "sigef.surveyor", project.sigef.surveyor], ["Credenciamento", "sigef.accreditationCode", project.sigef.accreditationCode], ["Datum", "geodesy.datum", project.geodesy.datum], ["Sistema de coordenadas", "geodesy.coordinateSystem", project.geodesy.coordinateSystem]]; const confidence = (path) => p.fieldDiagnostics.find((item) => item.field === path)?.confidence || "NÃO IDENTIFICADA"; return <section className="gr-panel gr-diagnostic"><div className="gr-diagnostic-head"><div><span className="gr-kicker">MODO DE DIAGNÓSTICO</span><h3>Conferir dados extraídos</h3></div><button onClick={() => setRaw(!raw)}>{raw ? "OCULTAR TEXTO EXTRAÍDO" : "VER TEXTO EXTRAÍDO"}</button></div><h4>Processamento</h4><ol className="gr-steps">{diagnostic.steps.map((step) => <li key={step.label} className={step.ok ? "ok" : "fail"}><span>{step.ok ? "✓" : "!"}</span><strong>{step.label}</strong><small>{step.detail}</small></li>)}</ol><div className="gr-diagnostic-grid"><div><h4>Arquivo</h4><p>Nome: <strong>{diagnostic.file.name}</strong></p><p>Tamanho: <strong>{(diagnostic.file.size / 1024).toLocaleString("pt-BR", { maximumFractionDigits: 1 })} KB</strong></p><p>Páginas: <strong>{diagnostic.file.pageCount}</strong></p><p>Texto nativo encontrado: <strong>{diagnostic.file.hasNativeText ? "SIM" : "NÃO"}</strong></p></div><div><h4>Geometria</h4><p>Tipo de coordenada: <strong>{p.coordinateType}</strong></p><p>Vértices encontrados: <strong>{project.vertices.length}</strong></p><p>Segmentos: <strong>{project.boundaries.length}</strong></p><p>Confrontantes: <strong>{names.size}</strong></p><p>Primeiro vértice: <strong>{value(valid[0]?.code)}</strong></p><p>Último vértice: <strong>{value(valid.at(-1)?.code)}</strong></p><p>Polígono fechado: <strong>{project.geometry ? "SIM" : "NÃO"}</strong></p></div></div><h4>Extração e confiança</h4><div className="gr-extraction">{extracted.map(([label, path, item]) => <div key={path}><span>{label}</span><strong>{value(item)}</strong><small>Confiança: {confidence(path)} · Extraído do Memorial SIGEF</small>{p.ambiguousFields.some((field) => field.field === path) && <em>Mais de uma informação possível encontrada. Selecione o valor correto.</em>}</div>)}</div><h4>Diagnóstico de vértices</h4><Table headers={["Ordem", "Vértice", "Tipo", "Latitude", "Longitude", "E", "N", "Altitude", "Status"]} rows={project.vertices.map((v, i) => [i + 1, value(v.code), value(v.type), format(v.latitude, 9), format(v.longitude, 9), format(v.east, 3), format(v.north, 3), format(v.altitude, 3), v.status])} /><h4>Diagnóstico de segmentos</h4><Table headers={["De", "Para", "Azimute", "Distância", "Confrontante", "Status"]} rows={project.boundaries.map((s) => [value(s.fromVertex), value(s.toVertex), value(s.azimuth), format(s.distance, 3), value(s.boundaryName), s.status])} />{raw && <pre className="gr-raw-text">{diagnostic.rawText || "Nenhum texto nativo extraído."}</pre>}</section>; }
function Table({ headers, rows = [], empty = "Nenhum dado disponível." }) { return <section className="gr-panel gr-table-wrap"><table><thead><tr>{headers.map((h) => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, i) => <tr key={i}>{row.map((cell, j) => <td key={j}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length}>{empty}</td></tr>}</tbody></table></section>; }
function featureVertices(feature) { const geometry = feature?.geometry || feature; const ring = geometry?.type === "Polygon" ? geometry.coordinates?.[0] : geometry?.type === "MultiPolygon" ? geometry.coordinates?.[0]?.[0] : []; const coordinates = ring?.length > 1 && ring[0][0] === ring.at(-1)[0] && ring[0][1] === ring.at(-1)[1] ? ring.slice(0, -1) : ring || []; return coordinates.map(([longitude, latitude, altitude]) => ({ code: "", type: "", latitudeDocument: null, longitudeDocument: null, longitudeDecimal: Number(longitude), latitudeDecimal: Number(latitude), longitude: Number(longitude), latitude: Number(latitude), east: null, north: null, altitude: Number.isFinite(altitude) ? altitude : null, coordinateSource: "KML" })); }
function mergeData(current, incoming) { return { property: { ...current.property, ...withoutEmpty(incoming.property) }, registry: { ...current.registry, ...withoutEmpty(incoming.registry) }, sigef: { ...current.sigef, ...withoutEmpty(incoming.sigef) }, geodesy: { ...current.geodesy, ...withoutEmpty(incoming.geodesy) }, vertices: incoming.vertices?.length ? incoming.vertices : current.vertices, boundaries: incoming.boundaries?.length ? incoming.boundaries : current.boundaries, geometry: incoming.geometry || current.geometry }; }
function applyMemorialToProject(current, incoming) { const next = applyMemorialData(current, incoming); return { ...next, dataOrigins: { ...(current.dataOrigins || {}), ...originsFor(incoming, "SIGEF/MEMORIAL") } }; }
function withoutEmpty(object = {}) { return Object.fromEntries(Object.entries(object).filter(([, item]) => item !== "" && item != null)); }
function originsFor(data, origin) { return Object.entries(data || {}).flatMap(([group, values]) => values && !Array.isArray(values) && typeof values === "object" ? Object.entries(values).filter(([, value]) => value !== "" && value != null).map(([key]) => [`${group}.${key}`, origin]) : []).reduce((result, [path, value]) => ({ ...result, [path]: value }), {}); }
function ParserDiagnosticReliable({ diagnostic, project }) { const [showAllText, setShowAllText] = useState(false); const parsed = diagnostic.parsed; const vertexDiagnostic=parsed.vertexDiagnostic||{found:project.vertices.length,structured:project.vertices.filter((item)=>item.status==="OK").length,rejected:project.vertices.filter((item)=>item.status!=="OK").length}; const rejected=parsed.rejectedVertices||[]; const extractedCount = project.boundaries.filter((item) => item.origin === "MEMORIAL").length; const reconstructedCount = project.boundaries.filter((item) => item.origin === "RECONSTRUÍDO").length; const confrontants = new Set(project.boundaries.filter((item) => item.origin === "MEMORIAL").map((item) => item.boundaryName).filter(Boolean)); return <section className="gr-panel gr-diagnostic"><div className="gr-diagnostic-head"><div><span className="gr-kicker">MODO DE DIAGNÓSTICO</span><h3>Interpretação técnica do Memorial</h3></div><button onClick={() => setShowAllText(!showAllText)}>{showAllText ? "OCULTAR TEXTO EXTRAÍDO" : "VER TEXTO EXTRAÍDO"}</button></div><div className="gr-diagnostic-grid"><div><h4>Arquivo</h4><p>Nome: <strong>{diagnostic.file.name}</strong></p><p>Páginas: <strong>{diagnostic.file.pageCount}</strong></p><p>Texto nativo: <strong>{diagnostic.file.hasNativeText ? "SIM" : "NÃO"}</strong></p></div><div><h4>Interpretação</h4><p>Vértices encontrados: <strong>{vertexDiagnostic.found}</strong></p><p>Vértices estruturados: <strong>{vertexDiagnostic.structured}</strong></p><p>Vértices rejeitados: <strong>{vertexDiagnostic.rejected}</strong></p><p>Segmentos extraídos do Memorial: <strong>{extractedCount}</strong></p><p>Segmentos reconstruídos: <strong>{reconstructedCount}</strong></p><p>Confrontantes extraídos: <strong>{confrontants.size}</strong></p></div></div>{rejected.length>0&&<><h4>Vértices rejeitados</h4><Table headers={["Código","Página","Texto original","Motivo da rejeição"]} rows={rejected.map((item)=>[value(item.code),item.page||"Não identificada",value(item.originalText),value(item.reason)])}/></>}<h4>Estrutura bruta dos segmentos</h4><pre className="gr-raw-text">{parsed.rawSegmentStructure?.length ? parsed.rawSegmentStructure.map((item) => `${item.line}: ${item.text}`).join("\n") : "Nenhuma estrutura documental de segmentos foi isolada. Use VER TEXTO EXTRAÍDO para conferir o documento completo."}</pre><h4>Segmentos documentais e reconstruídos</h4><Table headers={["Trecho", "Azimute documental", "Distância documental", "Confrontante", "Origem"]} rows={project.boundaries.map((item) => [`${item.fromVertex} → ${item.toVertex}`, value(item.azimuthDocumentRaw || item.azimuthDocument), item.distanceDocumentRaw || value(item.distanceDocument), value(item.boundaryName), item.origin])} />{showAllText && <pre className="gr-raw-text">{diagnostic.rawText || "Nenhum texto nativo extraído."}</pre>}</section>; }
function buildProcessingSteps(extracted, parsed, project) { const validVertices = project.vertices.filter((v) => v.status === "OK").length; return [{ label: "PDF carregado", ok: true, detail: `${extracted.pageCount} página(s)` }, { label: "Texto extraído", ok: extracted.hasNativeText, detail: extracted.hasNativeText ? `${extracted.text.length} caracteres` : "Nenhum texto nativo" }, { label: "Dados cadastrais identificados", ok: parsed.fieldDiagnostics.some((item) => item.value !== ""), detail: `${parsed.fieldDiagnostics.filter((item) => item.value !== "").length} campo(s)` }, { label: "Vértices identificados", ok: validVertices >= 3, detail: `${validVertices} válido(s) de ${project.vertices.length}` }, { label: "Segmentos identificados", ok: project.boundaries.length > 0, detail: `${project.boundaries.length} segmento(s)` }, { label: "Geometria reconstruída", ok: Boolean(project.geometry), detail: project.geometry ? "Polígono disponível" : "Geometria indisponível" }, { label: "Área calculada", ok: Number.isFinite(project.validation?.calculatedArea), detail: Number.isFinite(project.validation?.calculatedArea) ? `${format(project.validation.calculatedArea)} ha` : "Não calculada" }, { label: "Validação concluída", ok: Boolean(project.validation?.status), detail: project.validation?.status || "Não executada" }]; }
